import json, sys
after = json.load(sys.stdin)
with open('baseline-packages.json') as f:
    baseline = json.load(f)

# Build lookup: project_basename -> framework -> {pkg: version}
def build_map(data):
    m = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        m[name] = {}
        for fw in p['frameworks']:
            m[name][fw['framework']] = {pkg['id']: pkg['resolvedVersion'] for pkg in fw['topLevelPackages']}
    return m

b = build_map(baseline)
a = build_map(after)

changes = []
unchanged = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    for fw in sorted(set(list(b.get(proj,{}).keys()) + list(a.get(proj,{}).keys()))):
        bp = b.get(proj,{}).get(fw,{})
        ap = a.get(proj,{}).get(fw,{})
        for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
            bv = bp.get(pkg)
            av = ap.get(pkg)
            if bv != av:
                changes.append((proj, fw, pkg, bv or 'N/A', av or 'N/A'))
            else:
                unchanged.append((proj, fw, pkg, av))

if changes:
    print('CHANGES:')
    for c in changes:
        print(f'  {c[0]} ({c[1]}): {c[2]} {c[3]} -> {c[4]}')
else:
    print('NO CHANGES - fully version-neutral')

print(f'\nUnchanged: {len(unchanged)} package-framework entries')
" 2>&1

